# ---- 352 Oil and Gas Production I ----
H('352.d.1.A',3,"The first commercial oil well in the United States was drilled in Pennsylvania in:","1859",["1659","1759","1959"],"Drake's well was in 1859.")
H('352.d.1.A',4,"Oil drilling in Texas expanded greatly after the 1901 discovery at:","Spindletop",["Bay City","Big Bend","Palo Duro"],"Spindletop launched the Texas oil boom.")
H('352.d.1.B',3,"An offshore drilling platform is used to:","drill wells in the ocean",["grow crops","load trains","build roads"],"Offshore rigs reach sea-floor reservoirs.")
H('352.d.1.B',4,"The part of a rig that rotates the drill string is called the:","rotary table or top drive",["cafeteria","bunkhouse","windsock"],"The rotary system turns the pipe.")
H('352.d.1.C',3,"Directional drilling allows operators to:","steer a well toward a target that is not directly below the rig",["only drill straight down","avoid drilling","paint the well"],"Wells can be steered.")
H('352.d.1.C',4,"A mud motor in directional drilling helps by:","turning the bit without rotating the whole drill string",["cooling the crew","lighting the rig","measuring prices"],"Mud motors rotate the bit downhole.")
H('352.d.1.D',3,"Fishing in a well means:","retrieving lost tools or pipe from the borehole",["catching trout","repairing boats","selling fish"],"Fishing recovers stuck equipment.")
H('352.d.1.D',4,"A tool used to catch the top of a lost pipe in a well is called an:","overshot",["umbrella","anchor","bottle"],"Overshots grip the outside of the fish.")
H('352.d.1.E',3,"Casing is run in a well to:","protect the hole and isolate formations",["feed the crew","cool the rig","hold tools"],"Casing lines the well.")
H('352.d.1.E',4,"Cement is pumped around the casing to:","seal it and prevent fluid from moving between zones",["color the pipe","lower pressure only","warm the rock"],"Cement isolates zones.")
H('352.d.1.F',3,"Fluid pressure in a well is commonly measured in:","pounds per square inch (psi)",["feet","gallons","degrees only"],"psi is the common unit.")
H('352.d.1.F',4,"If the pressure of drilling mud is too low compared with formation pressure, the well could experience a:","kick",["picnic","holiday","nap"],"Underbalance can let formation fluids enter.")
H('352.d.1.G',3,"Flow in a new well may be started by:","perforating the casing and, if needed, reducing pressure in the well",["painting the wellhead","adding sand to the sea","shutting everything"],"Perforations open the pay zone.")
H('352.d.1.G',4,"When a reservoir has too little pressure to flow naturally, operators may use:","artificial lift such as a pump",["a fan","a bucket","a blanket"],"Pumps lift fluid to the surface.")
H('352.d.1.H',3,"The Christmas tree on a producing well controls:","the flow of fluids at the surface",["lighting of the rig","crew meals","office air"],"The tree has valves that control flow.")
H('352.d.1.H',4,"Tubing is the pipe inside the casing that:","carries oil and gas to the surface",["holds crew","stores water","lights the rig"],"Production tubing carries fluid.")
H('352.d.1.I',3,"Perforating a casing means:","making holes so oil or gas can enter the well",["painting it","bending it","burying it"],"Perforations connect well to formation.")
H('352.d.1.I',4,"After perforating, a well may be stimulated with acid or fracturing to:","improve flow from the formation",["decrease production","close the well","fill it with water"],"Stimulation increases productivity.")
H('352.d.1.J',3,"A packer is placed in a well completion to:","seal the space between tubing and casing",["feed the crew","measure wind","store cash"],"Packers isolate zones.")
H('352.d.1.J',4,"The plan that lists the equipment to be installed in a finished well is the:","completion design",["lunch plan","bus map","yearbook"],"Completion designs list tubing, packers, and tools.")
H('352.d.1.K',3,"A well log is a record of:","measurements taken in the wellbore",["crew birthdays","office rent","fuel prices"],"Logs record rock and fluid properties.")
