H('352.d.1.L',3,"A well that produces less than expected may be checked for problems such as:","damage near the wellbore or low reservoir pressure",["bad weather in another state","a school holiday","a bus delay"],"Analysts examine skin, pressure, and equipment.")
H('352.d.1.L',4,"Scale or paraffin buildup in tubing can cause a well to:","produce less",["produce more","stop needing pressure","turn to water"],"Deposits restrict flow.")
H('352.d.1.M',3,"A roughneck on a drilling rig works mainly on the:","rig floor handling pipe and equipment",["office desk","sales floor","bank counter"],"Roughnecks handle the pipe.")
H('352.d.1.M',4,"A good worker on a drilling crew must be able to:","follow safety rules and work as a team",["work alone only","ignore directions","avoid training"],"Safety and teamwork are essential.")
H('352.d.2.A',3,"Major equipment at a production site includes separators, tanks, and:","wellhead and pumps",["swing sets","cafeteria trays","sports gear"],"These are standard production items.")
H('352.d.2.A',4,"A separator at a production facility divides well fluid into oil, gas, and:","water",["sand only","salt only","smoke"],"Separators split the three phases.")
H('352.d.2.B',3,"Valves on the wellhead are used to:","control the flow of fluids",["warm the crew","paint the pipe","count visitors"],"Valves open and close flow.")
H('352.d.2.B',4,"The valve on a wellhead used to shut off flow in an emergency is the:","master valve",["garden valve","kitchen valve","party valve"],"The master valve is the main shutoff.")
H('352.d.2.C',3,"Following the process flow means tracing fluid from the wellhead through:","separators, treaters, and storage",["a classroom","a school","a bakery"],"The flow runs through processing equipment.")
H('352.d.2.C',4,"After separation, the gas is usually sent to a:","pipeline or processing plant",["pool","garden","school"],"Gas is sold through pipelines.")
H('352.d.2.D',3,"The wellhead is the equipment at the top of a well that:","supports the casing and tubing and controls flow",["stores crew meals","holds the office","paints the rig"],"It anchors and controls the well.")
H('352.d.2.D',4,"The casing head and tubing head are parts of the:","wellhead",["rig floor","mud pit","flare"],"These form the wellhead assembly.")
H('352.d.2.E',3,"A choke on a wellhead is used to:","regulate the rate of flow",["increase noise","cool the crew","measure time"],"Chokes restrict flow to control rate and pressure.")
H('352.d.2.E',4,"A pressure gauge on the wellhead lets operators:","monitor well pressure",["listen to music","count trucks","watch TV"],"Gauges show pressure.")
H('352.d.2.F',3,"Compared with a land wellhead, a subsea wellhead must be:","designed for high pressure and underwater use",["smaller than a pencil","made of paper","left unprotected"],"Subsea equipment faces deep-water conditions.")
H('352.d.2.F',4,"A high-pressure wellhead is built stronger than a low-pressure one because it must:","withstand higher internal pressures",["weigh less","cost less","hold less"],"Rating matches expected pressure.")
H('352.d.2.G',3,"A key difference between onshore and offshore facilities is that offshore sites:","are located at sea and have limited space",["have unlimited space","have no weather","need no safety"],"Platforms are compact and remote.")
H('352.d.2.G',4,"Supplies to an offshore platform are often delivered by:","boat or helicopter",["bicycle","school bus","train"],"Boats and helicopters serve platforms.")
H('352.d.2.H',3,"The Gulf of Mexico is known as a major region for:","offshore oil and gas production",["wheat farming","skiing","diamond mining"],"The Gulf is a leading offshore area.")
H('352.d.2.H',4,"The Marcellus Shale is a major natural gas region located in the:","northeastern United States",["Pacific Northwest","Southwest desert","Hawaii"],"It lies under Pennsylvania and nearby states.")
H('352.d.2.I',3,"Hydrogen sulfide (H2S) is dangerous because it is:","a toxic gas that can be deadly",["a harmless vapor","a food additive","a bottled drink"],"H2S is highly toxic.")
H('352.d.2.I',4,"Workers in areas where H2S may be present should carry:","a personal gas monitor",["a camera","a radio only","a lunch box only"],"Monitors alert workers to gas.")
H('352.d.2.J',3,"If a wellhead leaks, the problem can affect:","the flowlines and facilities connected to it",["only the weather","only another planet","only the moon"],"Production systems are linked.")
H('352.d.2.J',4,"A pressure drop at the wellhead can signal a problem in the:","connected pipeline or equipment",["school bell","sports team","grocery store"],"Connected systems reveal issues.")
H('352.d.2.K',3,"Monitoring a well includes regularly checking:","pressure, temperature, and flow rate",["school grades","lunch menus","sports scores"],"Production data are tracked.")
H('352.d.2.K',4,"Automated sensors that send well data to a control room are part of:","SCADA monitoring",["a mail route","a classroom game","a bus line"],"SCADA collects and sends data remotely.")
H('352.d.2.L',3,"A pumper is a worker who:","visits wells to check equipment and record data",["teaches school","bakes bread","drives a taxi"],"Pumpers inspect and maintain well sites.")
H('352.d.2.L',4,"Routine wellhead maintenance includes greasing valves and:","checking for leaks",["painting murals","repainting the sun","moving mountains"],"Preventive maintenance finds problems early.")
H('352.d.2.M',3,"Using a computer simulator to practice operating a wellhead is useful because it:","lets trainees learn without real-world risk",["replaces all safety rules","removes the need for training","pays the trainee"],"Simulators make training safer.")
H('352.d.2.M',4,"When troubleshooting, the first step is usually to:","gather data and identify symptoms",["guess","ignore alarms","shut down everything immediately"],"Good troubleshooting starts with data.")
H('352.d.2.N',3,"A manual shutdown is usually required when:","an unsafe condition such as a leak is detected",["the weather is nice","it is lunch time","a visitor arrives"],"Unsafe conditions warrant shutdown.")
H('352.d.2.N',4,"An automatic safety valve closes when:","pressure goes outside safe limits",["a bird passes","the radio plays","the sun rises"],"Safety devices respond to abnormal pressure.")
H('352.d.3.A',3,"Personal protective equipment on a well site includes a hard hat, safety glasses, and:","steel-toed boots",["sandals","flip-flops","bare feet"],"Boots protect feet.")
H('352.d.3.A',4,"Flame-resistant clothing is worn to protect workers from:","fire and flash hazards",["rain only","cold only","noise only"],"FR clothing resists burning.")
H('352.d.3.B',3,"OSHA is the federal agency that sets and enforces:","workplace safety standards",["tax rates","school schedules","road names"],"OSHA protects workers.")
H('352.d.3.B',4,"The Bureau of Safety and Environmental Enforcement (BSEE) regulates safety for:","offshore oil and gas operations",["school buses","food trucks","airports"],"BSEE oversees offshore operations.")

# ---- 353 Petroleum Industry Operations ----
H('353.d.1.A',3,"Before pipelines, crude oil was moved in:","wooden barrels by wagon",["jet planes","electric cars","satellites"],"Early oil moved in barrels.")
H('353.d.1.A',4,"Pipelines became popular because they:","move large volumes of oil cheaply and safely",["are the slowest method","need no maintenance","cost more than wagons"],"Pipelines are efficient.")
H('353.d.1.B',3,"Oil is transported over land by pipeline, rail, and:","tanker truck",["horse","hot air balloon","bicycle"],"Trucks move oil short distances.")
H('353.d.1.B',4,"A benefit of moving crude oil by rail is that it:","can reach places that have no pipeline",["needs no tracks","uses no fuel","is silent"],"Rail adds flexibility.")
H('353.d.1.C',3,"A hazard communication program tells workers about:","dangers of chemicals they handle",["lunch menus","school grades","sports teams"],"HazCom informs workers.")
H('353.d.1.C',4,"Drivers of crude oil tank trucks must follow rules from the:","Department of Transportation",["Department of Art","Department of Music","School Board"],"DOT regulates hauling.")
H('353.d.1.D',3,"Crude oil prices are affected by supply, demand, and:","global events",["school colors","lunch choices","hair styles"],"World events move prices.")
H('353.d.1.D',4,"When OPEC members agree to cut production, oil prices tend to:","rise",["fall","freeze","vanish"],"Lower supply raises prices.")
H('353.d.1.E',3,"Refined products such as gasoline reach consumers through:","distribution terminals and service stations",["school hallways","museums","libraries"],"Terminals supply stations.")
H('353.d.1.E',4,"Wholesale sales of fuel are made to businesses, while retail sales are made to:","individual consumers",["no one","planets","governments only"],"Retail serves the public.")
H('353.d.1.F',3,"Exploration companies create new oil and gas supplies by:","finding and drilling new reserves",["selling gas","refining gas","buying gas"],"They add supply.")
H('353.d.1.F',4,"Service companies support drilling by providing:","equipment, crews, and technical services",["school books","groceries","clothing"],"Service firms support operators.")
H('353.d.1.G',3,"An independent oil company usually focuses on:","exploration and production only",["refining, shipping, and retail","teaching","manufacturing toys"],"Independents specialize in upstream work.")
H('353.d.1.G',4,"A company that explores, produces, refines, and sells products is called:","integrated",["isolated","independent","inactive"],"Integrated firms span the chain.")
H('353.d.1.H',3,"Before investing in a drilling prospect, investors consider risk, cost, and:","expected return",["school colors","lunch menu","bus route"],"They weigh return against risk.")
H('353.d.1.H',4,"A dry hole is a well that:","finds no commercial oil or gas",["produces too much","never gets drilled","is on land"],"Dry holes are financial losses.")
H('353.d.1.I',3,"An investment of $1,000,000 that returns $1,200,000 earned what percent gain?","20 percent",["12 percent","2 percent","120 percent"],"Gain of 200,000 divided by 1,000,000 is 20 percent.")
H('353.d.1.I',4,"A project costs $500,000 and yields $50,000 profit in a year. The rate of return is:","10 percent",["5 percent","50 percent","1 percent"],"50,000 / 500,000 = 10 percent.")
H('353.d.2.A',3,"Drilling cuttings and waste fluids are managed by:","hauling to approved disposal sites or recycling",["pouring in creeks","burning in schoolyards","burying near homes"],"Wastes follow disposal rules.")
H('353.d.2.A',4,"A lined pit is used to:","contain waste fluids and prevent seepage into soil",["grow plants","hold crew","store money"],"Liners protect soil and groundwater.")
H('353.d.2.B',3,"Booms are placed on water after an oil spill to:","contain and limit the spread of oil",["start fires","feed fish","raise prices"],"Booms corral oil.")
H('353.d.2.B',4,"Skimmers are used in spill response to:","remove oil from the water surface",["add oil","cool the sea","warm the sea"],"Skimmers recover oil.")
H('353.d.2.C',3,"Refineries reduce environmental impact by capturing:","vapors and emissions with control equipment",["more smoke","wastewater","fuel"],"Control devices limit releases.")
H('353.d.2.C',4,"Recycling water within a refinery reduces:","freshwater withdrawal",["safety","production","oil quality"],"Reuse conserves water.")
H('353.d.3.A',3,"A petroleum company that invests in solar and wind projects is exploring:","renewable energy sources",["more coal only","less power","only oil"],"Many firms diversify.")
H('353.d.3.A',4,"Biofuels such as ethanol are made from:","plant materials",["crude oil only","coal only","uranium"],"Ethanol comes from crops like corn.")
H('353.d.3.B',3,"A major challenge for the petroleum industry is meeting demand while:","reducing emissions",["raising emissions","ending jobs","ignoring rules"],"Balance demand and environment.")
H('353.d.3.B',4,"Price swings are a challenge because they make it hard to:","plan investments",["tell time","build roads","see colors"],"Volatility affects planning.")
H('353.d.3.C',3,"Carbon capture and storage is a technology that:","traps carbon dioxide before it enters the atmosphere",["makes more CO2","burns more coal","drains lakes"],"CCS reduces emissions.")
H('353.d.3.C',4,"Advanced batteries could help the energy system by:","storing electricity for later use",["wasting electricity","ending the grid","removing power lines"],"Storage balances supply and demand.")
H('353.d.3.D',3,"A nontechnical way to reduce energy demand is to:","change habits, such as carpooling",["build bigger engines","leave lights on","idle cars"],"Behavior changes cut use.")
H('353.d.3.D',4,"Building codes that require better insulation are an example of:","a policy solution to reduce energy use",["a weather event","a new planet","a toy"],"Policies can lower demand.")

# ---- 354 Oil Field Hydraulics ----
H('354.d.1.A',3,"Hydraulic fracturing has been used by service companies such as Halliburton since the:","late 1940s",["1700s","1800s","2020s"],"Commercial fracturing began in 1949.")
H('354.d.1.A',4,"Pioneers of modern horizontal shale development include Mitchell Energy in the:","Barnett Shale of Texas",["Sahara Desert","Alaska ice","Hawaii coast"],"Mitchell Energy developed Barnett Shale fracturing.")
H('354.d.1.B',3,"Hydraulic fracturing became important to US energy because it made it possible to produce oil and gas from:","tight shale formations",["open lakes","deserts","oceans"],"Fracturing unlocked shale.")
H('354.d.1.B',4,"Combining hydraulic fracturing with horizontal drilling led to a rapid increase in:","US oil and gas production",["coal mining only","wind power only","solar power only"],"The combination drove the shale boom.")
H('354.d.1.C',3,"Hydraulic technology in oil fields helped North America become:","one of the world's largest oil and gas producers",["an importer of all fuel","a coal-free nation","a nuclear-only country"],"The US became a leading producer.")
H('354.d.1.C',4,"An impact of shale development on energy prices has been:","lower natural gas prices for consumers",["higher gas prices only","no change","ending of gas use"],"More supply lowered prices.")
H('354.d.1.D',3,"New oil and natural gas production from shale supports North American:","energy independence and jobs",["unemployment","school closures","fuel shortages only"],"It increased domestic supply.")
H('354.d.1.D',4,"Increased natural gas production has led many power plants to switch from:","coal to natural gas",["gas to coal","wind to coal","hydro to oil"],"Cheap gas replaced coal in many plants.")
H('354.d.2.A',3,"A pneumatic system uses:","compressed air to do work",["flowing oil","sunlight","magnets"],"Pneumatics use compressed gas.")
H('354.d.2.A',4,"A pneumatic system needs an air compressor, a receiver tank, and:","valves and actuators",["a diary","a paintbrush","a lunchbox"],"These are functional components.")
H('354.d.2.B',3,"Pneumatic pressure is most commonly measured in:","psi",["feet","pounds","seconds"],"psi is pounds per square inch.")
H('354.d.2.B',4,"Atmospheric pressure at sea level is about:","14.7 psi",["147 psi","1.47 psi","0 psi"],"Standard atmosphere is 14.7 psi.")
H('354.d.2.C',3,"A hydraulic system uses:","a liquid under pressure to transmit force",["air only","sunlight","magnets"],"Hydraulics use incompressible fluid.")
H('354.d.2.C',4,"A hydraulic system typically has a reservoir, a pump, valves, and:","an actuator such as a cylinder",["a pencil","a clock","a lamp"],"Actuators do the work.")
H('354.d.2.D',3,"Hydraulic pressure is measured in:","psi",["volts","meters per second","ohms"],"psi is a pressure unit.")
H('354.d.2.D',4,"Hydraulics is the study of how liquids:","transmit force and motion",["grow plants","make sound","change color"],"Fluids transmit force.")
H('354.d.3.A',3,"A basic safety rule in pneumatics is to always wear:","safety glasses",["sunglasses","sandals","headphones only"],"Eye protection is required.")
H('354.d.3.A',4,"Before disconnecting pneumatic components, you should first:","release the pressure from the system",["raise the pressure","ignore the gauge","tighten fittings"],"Depressurize before service.")
H('354.d.3.B',3,"Never point compressed air at yourself or others because it can:","cause serious injury",["feel cool","clean the air","save energy"],"High-pressure air can injure.")
H('354.d.3.B',4,"A worn or cracked air hose should be:","replaced before use",["used anyway","taped","ignored"],"Damaged hoses can burst.")
H('354.d.3.C',3,"A pressure regulator in a pneumatic circuit:","keeps pressure at a set safe level",["raises pressure without limit","removes air","adds oil"],"Regulators control downstream pressure.")
H('354.d.3.C',4,"If the regulator is set too high, components may be:","damaged or unsafe",["quieter","colder","cleaner"],"Excess pressure can damage parts.")
H('354.d.4.A',3,"A double-acting pneumatic cylinder uses air pressure to move the piston in:","both directions",["one direction only","no direction","a circle only"],"Air extends and retracts the rod.")
H('354.d.4.A',4,"Compared with a single-acting cylinder, a double-acting cylinder does not rely on a:","return spring",["compressor","valve","hose"],"Air does the return stroke.")
H('354.d.4.B',3,"A five-way three-position valve can route air to extend, retract, or:","hold or stop the cylinder",["melt the cylinder","blow the whistle","paint the cylinder"],"The center position stops or holds.")
H('354.d.4.B',4,"A directional control valve is used to:","change the path of air flow",["warm the room","measure time","hold paper"],"Valves direct flow.")
H('354.d.4.C',3,"A quick-connect fitting allows hoses to be:","connected and disconnected without tools",["welded together","permanently glued","painted"],"Quick-connects speed assembly.")
H('354.d.4.C',4,"A quick-connect fitting usually has a:","sleeve that locks the plug in place",["bell","lock of hair","candle"],"The sleeve holds the connection.")
H('354.d.4.D',3,"Before connecting a quick-connect to a pressurized supply, you should:","make sure the circuit is set up and the supply is off or low",["do nothing","stand on the hose","cut the hose"],"Safe connection starts with controlled pressure.")
H('354.d.4.D',4,"After connecting a pneumatic circuit, you should check for:","air leaks",["noise from the sky","paint","gloves"],"Leaks waste air and cause hazards.")
H('354.d.5.A',3,"ISO symbols on a hydraulic schematic represent:","components such as pumps and cylinders",["paintings","stars","words in a poem"],"Symbols show standard parts.")
H('354.d.5.A',4,"Lines on a hydraulic schematic show:","the paths fluid takes",["cloud shapes","sports scores","the weather"],"Lines represent fluid conductors.")
H('354.d.5.B',3,"A hydraulic schematic should show the pump, valve, cylinder, and:","reservoir",["swimming pool","bicycle","television"],"The reservoir is part of the circuit.")
H('354.d.5.B',4,"When drawing a schematic, you should label:","each component and the flow direction",["only the colors","only the page","only the date"],"Labels improve clarity.")
H('354.d.6.A',3,"Force equals pressure multiplied by:","area",["time","height","speed"],"F = P x A.")
H('354.d.6.A',4,"A cylinder with a piston area of 4 square inches and 1,000 psi produces a force of:","4,000 pounds",["250 pounds","1,004 pounds","996 pounds"],"4 x 1,000 = 4,000.")
H('354.d.6.B',3,"Pascal's Law says pressure applied to a confined fluid is transmitted:","equally throughout the fluid",["only upward","only downward","not at all"],"Pressure is transmitted equally.")
H('354.d.6.B',4,"A hydraulic jack lifts a heavy car by using Pascal's Law to:","multiply force",["destroy force","delete force","hide force"],"A small piston force produces a larger output.")
H('354.d.6.C',3,"A hydraulic pump converts mechanical energy into:","fluid flow and pressure",["sound","light","heat only"],"Pumps move fluid.")
H('354.d.6.C',4,"A hydraulic motor converts fluid power into:","rotating mechanical motion",["light","sound","food"],"Motors produce rotation.")
H('354.d.6.D',3,"A single-acting hydraulic cylinder uses fluid to move in:","one direction, returning by spring or load",["both directions with fluid","no direction","a circle"],"The return is not powered by fluid.")
H('354.d.6.D',4,"A double-acting hydraulic cylinder can push and:","pull with fluid power",["only rest","only float","only spin"],"Fluid powers both strokes.")

# ---- 355 Well Completions ----
H('355.d.1.A',3,"The well completion phase prepares a drilled well to:","produce oil or gas",["be abandoned","sell lunch","grow crops"],"Completion makes the well productive.")
H('355.d.1.A',4,"Hydrocarbons are made accessible by connecting the wellbore to the pay zone through:","perforations",["umbrellas","painting","insulation"],"Perforations connect formation and well.")
H('355.d.1.B',3,"Computer modeling is used in completion design to:","predict well performance and test options",["replace all equipment","guess randomly","ignore data"],"Models help compare designs.")
H('355.d.1.B',4,"A completion engineer uses reservoir data to decide on:","the best way to produce the well",["lunch menus","bus times","fashion"],"Design is data driven.")
H('355.d.1.C',3,"An open hole completion leaves the producing section:","uncased",["fully cased","buried","flooded with cement"],"Open hole has no casing across the pay zone.")
H('355.d.1.C',4,"Sand control completions keep formation sand from:","entering the well and damaging equipment",["improving oil","adding oil","lighting the rig"],"Screens and gravel packs block sand.")
H('355.d.1.D',3,"A conventional completion typically includes casing, tubing, and:","a packer",["a tent","a tire","a sign"],"A packer seals the annulus.")
H('355.d.1.D',4,"Tubing is run inside casing so that fluids:","flow through a smaller, controlled path",["leave the well","freeze","burn"],"Tubing carries produced fluids.")
H('355.d.2.A',3,"Health and safety standards for well sites are designed to:","protect workers and the environment",["slow work for no reason","reduce wages","increase accidents"],"Standards prevent harm.")
H('355.d.2.A',4,"A job safety analysis (JSA) is done before a task to:","identify hazards and plan controls",["pick teams","order food","set prices"],"JSAs reduce risk.")
H('355.d.2.B',3,"A tool used to measure depth of the well in completions is a:","wireline tool",["bicycle pump","paintbrush","mixer"],"Wireline tools run in the well.")
H('355.d.2.B',4,"Blowout preventers (BOPs) are used to:","control well pressure and prevent uncontrolled flow",["start the engine","cool the crew","lower the flag"],"BOPs seal the well.")
H('355.d.2.C',3,"Spending more on safety training usually helps a company avoid:","costly accidents and downtime",["income","growth","profit"],"Safety saves money.")
H('355.d.2.C',4,"A serious well-site accident can cost a company in injuries, fines, and:","lost production and reputation",["new friends","free fuel","extra holidays"],"Accidents have large costs.")
H('355.d.3.A',3,"Drilling mud helps the drilling process by:","cooling the bit and carrying cuttings to the surface",["feeding the crew","painting the rig","shortening the well"],"Mud has several functions.")
H('355.d.3.A',4,"A generic well design includes surface casing, intermediate casing, and:","production casing",["roof shingles","paint","sails"],"These are typical casing strings.")
H('355.d.3.B',3,"Cuttings produced during drilling are usually moved to a disposal area by:","trucks or pipelines to an approved site",["boats to schools","balloons","bicycles"],"Cuttings require proper disposal.")
H('355.d.3.B',4,"A platform well is drilled from a:","fixed or floating structure at sea",["classroom","barn","stadium"],"Platforms support offshore wells.")
H('355.d.3.C',3,"A reservoir formation is important because it:","holds the oil or gas",["makes the weather","grows crops","keeps time"],"The reservoir stores hydrocarbons.")
H('355.d.3.C',4,"Evaluating a formation helps decide whether a well is:","commercially worth completing",["pretty","loud","old"],"Economics depend on the formation.")
H('355.d.4.A',3,"A safety plan for a well site should include emergency procedures and:","protective equipment requirements",["lunch menus","bus routes","art projects"],"Plans cover people and procedures.")
H('355.d.4.A',4,"Before starting high-pressure work, the crew holds a meeting to review:","hazards and responsibilities",["movies","sports","fashion"],"Pre-job meetings improve safety.")
H('355.d.4.B',3,"A flow meter measures:","how much fluid moves through a line",["noise level","wind color","temperature of the sun"],"Meters quantify flow.")
H('355.d.4.B',4,"Oil, gas, and water flows from a well are typically separated and measured at the:","separator",["classroom","parking lot","gift shop"],"Separators measure phases.")
H('355.d.4.C',3,"Surface well testing must include steps to prevent:","uncontrolled releases and fires",["good weather","sunlight","wind"],"Precautions protect crews.")
H('355.d.4.C',4,"During flowback, workers should keep ignition sources away because gas can be:","flammable",["sweet","cold","blue"],"Natural gas can ignite.")
H('355.d.4.D',3,"Knowing the surroundings before well work helps workers avoid:","hazards such as power lines and neighbors",["rain","lunch","weekends"],"Site awareness prevents accidents.")
H('355.d.4.D',4,"Wells near homes or streams require extra care to protect:","people and water resources",["only the crew","only equipment","only fuel"],"Environmental sensitivity matters.")
H('355.d.5.A',3,"Core analysis is performed on rock samples to learn about:","porosity and permeability",["popularity","sound","weather"],"Cores reveal reservoir properties.")
H('355.d.5.A',4,"A core is a cylinder of rock that is:","cut and brought to the surface for study",["painted","melted","buried"],"Cores are physical samples.")
H('355.d.5.B',3,"Core analysis data are combined with well logs to:","better understand the reservoir",["raise prices","slow drilling","remove casing"],"Combining data improves interpretation.")
H('355.d.5.B',4,"High porosity and permeability in a core suggest the rock can:","store and produce fluids well",["not store fluids","only hold air","be useless"],"Both properties support production.")
H('355.d.5.C',3,"Well logging uses instruments lowered into the well to measure:","rock and fluid properties",["student grades","bus routes","lunch cost"],"Logging tools record data.")
H('355.d.5.C',4,"Resistivity logs help identify zones containing:","hydrocarbons rather than salt water",["students","books","clouds"],"Hydrocarbons resist electric current.")
H('355.d.5.D',3,"Formation testing can include collecting:","fluid and pressure samples from the formation",["school pictures","maps of the moon","food orders"],"Testers sample fluids and measure pressure.")
H('355.d.5.D',4,"A formation tester is run in a well to measure:","pressure and fluid samples at selected depths",["the weather","surface traffic","cell service"],"Testers confirm productivity.")
H('355.d.5.E',3,"A drill stem test (DST) is run to:","test the flow potential of a formation",["paint the rig","cool the crew","train students"],"DSTs flow the formation briefly.")
H('355.d.5.E',4,"A drill stem test uses a tool string run on:","the drill pipe",["a kite string","a garden hose","a rope ladder"],"The test tools are on drill pipe.")
H('355.d.5.F',3,"DST results help engineers determine how much fluid will flow and at what:","pressure",["color","taste","size of the crew"],"They measure flow and pressure.")
H('355.d.5.F',4,"A DST that shows strong flow rates would suggest the formation is:","likely productive",["useless","made of glass","dry for sure"],"Flow indicates productivity.")
H('355.d.5.G',3,"The cost of a completion includes equipment, labor, and:","services such as logging and perforating",["prizes","parties","tickets"],"Completion costs add up.")
H('355.d.5.G',4,"A company compares completion costs with expected production to decide if the well is:","economically viable",["fun","pretty","famous"],"Economics drive decisions.")

# ---- 356 Process Technology ----
H('356.d.1.A',3,"Industries that use process technology include chemical plants, refineries, and:","power plants",["bakeries only","toy stores","movie theaters"],"Process operators work in these plants.")
H('356.d.1.A',4,"A process technician in a refinery works to monitor:","units that turn crude oil into products",["school buses","grocery shelves","retail sales"],"Technicians monitor refining units.")
H('356.d.1.B',3,"A process operator monitors equipment, records data, and:","responds to alarms",["teaches art","drives a bus","paints houses"],"Operators watch and control the process.")
H('356.d.1.B',4,"An entry-level process technology job typically requires:","a high school diploma and often an associate degree",["no education","a PhD","a law degree"],"Many programs offer two-year degrees.")
H('356.d.1.C',3,"Technical vocabulary such as valve, flow, and temperature should be:","used correctly when communicating on the job",["avoided","misspelled","ignored"],"Clear terms prevent mistakes.")
H('356.d.1.C',4,"Accurate shift logs are important because they:","pass information to the next shift",["entertain readers","waste time","add noise"],"Logs communicate status.")
H('356.d.1.D',3,"Automation and artificial intelligence are emerging issues because they change:","how plants are controlled and staffed",["the weather","the calendar","the moon"],"Technology changes plant work.")
H('356.d.1.D',4,"Cybersecurity is an emerging issue for process plants because control systems can be:","targeted by hackers",["painted","muted","lost"],"Connected systems face threats.")
H('356.d.1.E',3,"An instrument that measures temperature in a pipe is a:","thermocouple",["compass","telescope","stopwatch"],"Thermocouples sense temperature.")
H('356.d.1.E',4,"A transmitter sends a signal from a sensor to a:","control room",["bakery","mailbox","playground"],"Signals travel to controllers.")
H('356.d.2.A',3,"A valve that allows flow in only one direction is a:","check valve",["bicycle valve","party valve","garden valve"],"Check valves prevent backflow.")
H('356.d.2.A',4,"A centrifugal pump moves fluid by:","spinning an impeller",["rubbing sticks","freezing it","magnet only"],"Impellers add energy to fluid.")
H('356.d.2.B',3,"A piping and instrumentation diagram (P&ID) shows:","pipes, equipment, and instruments in a process",["a school map","a family tree","a menu"],"P&IDs are process maps.")
H('356.d.2.B',4,"On a P&ID, a circle with letters such as TI usually represents:","an instrument such as a temperature indicator",["a ball game","a lunch tray","a clock"],"Circles show instruments.")
H('356.d.3.A',3,"A block flow diagram gives a:","simple overview of a process",["detailed wiring plan","recipe for cookies","floor plan of a house"],"It shows major steps.")
H('356.d.3.A',4,"A process flow diagram (PFD) is more detailed than a block diagram and shows major:","equipment and flow streams",["hair styles","music","clothing"],"PFDs list equipment and flows.")
H('356.d.3.B',3,"A circuit schematic uses standard symbols to show:","electrical components and connections",["plants","recipes","clouds"],"Schematics show circuits.")
H('356.d.3.B',4,"In a schematic, a zigzag line usually represents a:","resistor",["battery","switch","fuse"],"The zigzag symbol is a resistor.")
H('356.d.3.C',3,"Building quality, reliability, and safety into a process begins with:","good design and preventive maintenance",["ignoring alarms","skipping checks","random changes"],"Design and maintenance prevent failures.")
H('356.d.3.C',4,"Statistical process control is used to:","detect when a process drifts from its target",["raise prices","find friends","decorate"],"SPC monitors variation.")
H('356.d.3.D',3,"Voltage, current, and resistance are related by:","Ohm's law",["Newton's law","Boyle's law","Murphy's law"],"V = I x R.")
H('356.d.3.D',4,"A circuit with 12 volts and 4 ohms of resistance has a current of:","3 amps",["48 amps","8 amps","16 amps"],"I = V / R = 12 / 4 = 3.")
H('356.d.4.A',3,"Lockout/tagout is a safety procedure that prevents:","equipment from starting during maintenance",["lunch breaks","phone calls","weather"],"It isolates energy sources.")
H('356.d.4.A',4,"Confined space entry requires a permit, gas testing, and:","an attendant outside",["a party","a nap","music"],"Confined spaces are hazardous.")
H('356.d.4.B',3,"A safety data sheet (SDS) lists information about a chemical's:","hazards and safe handling",["price only","color only","movie rating"],"SDSs communicate hazards.")
H('356.d.4.B',4,"Standard operating procedures should be followed:","exactly as written unless changed through proper approval",["whenever convenient","never","only on Mondays"],"Procedures protect people.")
H('356.d.4.C',3,"Improper maintenance can lead to equipment failure, injuries, and:","environmental releases",["good luck","clean air","extra holidays"],"Failures can harm people and environment.")
H('356.d.4.C',4,"Skipping a required inspection is an example of:","negligence",["precision","teamwork","innovation"],"Negligence is failing to do required work.")
H('356.d.4.D',3,"A micrometer or caliper is used to:","measure small dimensions precisely",["weigh ships","play music","carry water"],"Precision tools measure size.")
H('356.d.4.D',4,"Calibrating an instrument ensures it:","gives accurate readings",["looks new","costs less","makes noise"],"Calibration checks accuracy.")
H('356.d.4.E',3,"The agency that sets workplace safety rules in the United States is:","OSHA",["NASA","NBA","FIFA"],"OSHA regulates worker safety.")
H('356.d.4.E',4,"The EPA is most concerned with protecting:","the environment",["sports leagues","television ratings","stock prices"],"EPA enforces environmental rules.")
H('356.d.5.A',3,"A technician computes the volume of a rectangular tank by multiplying length by width by:","height",["color","name","age"],"V = l x w x h.")
H('356.d.5.A',4,"A tank is 4 ft long, 3 ft wide, and 2 ft deep. Its volume is:","24 cubic feet",["9 cubic feet","12 cubic feet","14 cubic feet"],"4 x 3 x 2 = 24.")
H('356.d.5.B',3,"A reading of 0.25 gallons expressed as a fraction is:","1/4",["1/2","2/5","1/8"],"0.25 = 1/4.")
H('356.d.5.B',4,"To add 1/2 and 0.25, a technician may convert both to:","decimals or fractions with a common form",["colors","names","times"],"Use consistent forms.")
H('356.d.5.C',3,"Measurement uncertainty is caused by factors such as:","instrument limits and reading errors",["luck","moonlight","music"],"Every measurement has uncertainty.")
H('356.d.5.C',4,"Using a more precise instrument usually makes uncertainty:","smaller",["larger","negative","random"],"Better instruments reduce uncertainty.")
H('356.d.5.D',3,"In the order of operations, calculations in parentheses are done:","first",["last","never","only once"],"Parentheses come first.")
H('356.d.5.D',4,"What is 2 + 3 x 4?","14",["20","24","9"],"Multiply first: 3x4 = 12, plus 2 = 14.")
H('356.d.5.E',3,"The cross-sectional area of a round pipe is found with the formula for the area of a:","circle",["triangle","square","line"],"A = pi r squared.")
H('356.d.5.E',4,"A pipe has a radius of 2 inches. Using pi = 3.14, its cross-sectional area is about:","12.56 square inches",["6.28 square inches","25.12 square inches","4 square inches"],"3.14 x 4 = 12.56.")
H('356.d.5.F',3,"Estimating a measurement before calculating helps a technician:","check that the final answer is reasonable",["avoid math","waste time","lose data"],"Estimates catch errors.")
H('356.d.5.F',4,"A tank holds about 1,000 gallons and the pump moves 50 gallons per minute. The time to fill is about:","20 minutes",["5 minutes","50 minutes","500 minutes"],"1,000 / 50 = 20.")
H('356.d.5.G',3,"The number 4,500,000 written in scientific notation is:","4.5 x 10^6",["45 x 10^5","4.5 x 10^5","0.45 x 10^6 only"],"Move the decimal six places.")
H('356.d.5.G',4,"In the metric system, one kilometer equals:","1,000 meters",["100 meters","10 meters","10,000 meters"],"Kilo means thousand.")
H('356.d.5.H',3,"Plotting readings from a gauge over time on a graph shows:","trends",["names","stories","jokes"],"Graphs reveal patterns.")
H('356.d.5.H',4,"A technician calculates the mean of four readings 10, 12, 14, and 12. The mean is:","12",["10","14","48"],"48 / 4 = 12.")
H('356.d.5.I',3,"A drawing has a scale of 1 inch = 5 feet. A line 3 inches long represents:","15 feet",["8 feet","3 feet","1.5 feet"],"3 x 5 = 15.")
H('356.d.5.I',4,"If a scaled drawing shows a pipe 2.5 inches long at a scale of 1 inch = 4 feet, the actual length is:","10 feet",["6.5 feet","1.6 feet","8 feet"],"2.5 x 4 = 10.")
H('356.d.5.J',3,"If 2 gallons of additive are used per 50 gallons of product, how many gallons are needed for 150 gallons?","6 gallons",["3 gallons","4 gallons","8 gallons"],"150 is 3 times 50, so 3 x 2 = 6.")
H('356.d.5.J',4,"A ratio of 3:5 means that for every 3 parts of A there are:","5 parts of B",["3 parts of B","8 parts of B","2 parts of B"],"Ratios compare quantities.")
H('356.d.6.A',3,"To solve a problem on a process unit, a technician first should:","define the problem clearly",["guess","panic","ignore it"],"Problem solving starts with definition.")
H('356.d.6.A',4,"Breaking a problem into smaller parts helps in finding:","the root cause",["more problems","more noise","extra work only"],"Decomposition reveals causes.")
H('356.d.6.B',3,"When evaluating information for a problem, a technician should check whether it is:","accurate and relevant",["long","colorful","old"],"Quality information supports decisions.")
H('356.d.6.B',4,"Data from an instrument that has not been calibrated should be:","treated with caution",["trusted blindly","used for all decisions","hidden"],"Uncalibrated data may be wrong.")
H('356.d.6.C',3,"Fishbone diagrams and the 5 Whys are tools for finding:","root causes",["lunch spots","friends","dates"],"They help trace causes.")
H('356.d.6.C',4,"Comparing several possible solutions before choosing is part of:","critical thinking",["guessing","delay","fear"],"Critical thinkers weigh options.")
H('356.d.6.D',3,"Technical research for a decision may use manuals, standards, and:","manufacturer data",["rumors","gossip","jokes"],"Authoritative sources are best.")
H('356.d.6.D',4,"Before changing a process, a technician should research whether the change is:","safe and approved",["quick","cheap only","fun"],"Management of change requires approval.")
H('356.d.7.A',3,"A simple model of a process system, such as a tank and pump setup, can be built to:","test ideas safely",["replace the plant","skip training","save no time"],"Models allow safe testing.")
H('356.d.7.A',4,"A computer simulation of a distillation column allows trainees to:","practice operations without real risk",["avoid learning","shut down actual plants","remove all rules"],"Simulations are safe practice.")
H('356.d.7.B',3,"A student adjusts the valve in a mockup to raise the tank level to a goal. This shows how to:","achieve a goal using a simple model",["destroy the model","avoid the task","ignore the goal"],"Mockups teach control.")
H('356.d.7.B',4,"In a level control loop, the controller opens or closes a valve to keep the level:","at a set point",["random","at zero","at maximum always"],"Controllers hold set points.")
H('356.d.7.C',3,"Executing a mockup includes starting equipment in the correct:","sequence",["color","time zone","language"],"Sequence matters.")
H('356.d.7.C',4,"After executing a mockup, the team should compare results to:","the goal",["the weather","the lunch menu","the bus schedule"],"Results are compared to the goal.")
H('356.d.7.D',3,"Choosing the right safety equipment for a task depends on:","the hazards present",["the color of the helmet","the weather forecast","the time"],"Hazards drive PPE selection.")
H('356.d.7.D',4,"Chemical splash goggles are chosen over regular safety glasses when:","liquids may splash into the eyes",["it is sunny","it is dark","the work is quiet"],"Goggles seal against splashes.")
H('356.d.7.E',3,"Calculations in process work often involve flow, temperature, and:","pressure",["flavor","fashion","fame"],"These are core variables.")
H('356.d.7.E',4,"To convert 5,280 feet to miles, you should divide by:","5,280",["52.8","1,000","12"],"There are 5,280 feet in a mile.")
H('356.d.7.F',3,"Trends on a control room display help operators see:","how a variable changes over time",["the weather","the news","the clock only"],"Trends show history.")
H('356.d.7.F',4,"An alarm on a control screen means that a measurement has crossed:","a limit",["a street","a border","a line in a book"],"Alarms signal limit violations.")
H('356.d.7.G',3,"Simulations help build critical thinking by letting trainees:","troubleshoot problems and see the results",["watch movies","avoid decisions","guess only"],"Practice builds judgment.")
H('356.d.7.G',4,"During a simulated upset, the best response is to:","follow procedures and diagnose systematically",["panic","shut everything randomly","ignore the alarm"],"Systematic response works best.")
H('356.d.8.A',3,"A conclusion is valid when it is:","supported by the data",["based on opinion only","popular","loud"],"Valid conclusions follow from data.")
H('356.d.8.A',4,"A small sample size can weaken a conclusion because it may:","not represent the whole",["be too exact","be too large","be too colorful"],"Small samples are less reliable.")
H('356.d.8.B',3,"A line graph is best for showing:","change over time",["parts of a whole only","names","places only"],"Line graphs show trends.")
H('356.d.8.B',4,"A table is useful for recording data because it:","organizes values for comparison",["hides values","adds noise","removes data"],"Tables organize data.")

# ---- 357 Petroleum Safety ----
H('357.d.1.A',3,"The agency that regulates workplace safety in the United States is:","OSHA",["FIFA","NASA","NBA"],"OSHA regulates worker safety.")
H('357.d.1.A',4,"The Texas Railroad Commission regulates the Texas:","oil and gas industry",["school buses","banks","airlines"],"The RRC oversees oil and gas.")
H('357.d.1.B',3,"OSHA's Process Safety Management standard applies to facilities that handle:","highly hazardous chemicals",["only paper","only toys","only food"],"PSM covers hazardous chemicals.")
H('357.d.1.B',4,"A worker who sees a violation of a safety standard should:","report it through the proper channel",["hide it","post it online only","ignore it"],"Reporting protects workers.")
H('357.d.1.C',3,"Safety programs used along the Gulf Coast often include training such as:","H2S awareness and first aid",["cooking class","art class","dance class"],"Industry sites require this training.")
H('357.d.1.C',4,"A site safety orientation is given to:","all new workers and visitors",["no one","only managers","only students"],"Everyone must know site rules.")
H('357.d.1.D',3,"A hot work permit is required before:","welding or cutting near flammable materials",["reading","walking","eating"],"Permits control ignition sources.")
H('357.d.1.D',4,"A permit-to-work system is an administrative control that:","authorizes and documents hazardous work",["pays workers","orders lunch","schedules breaks"],"Permits manage risk.")
H('357.d.1.E',3,"Eyewash stations must be:","tested regularly and kept clear",["hidden","locked","removed"],"They must work in emergencies.")
H('357.d.1.E',4,"A gas detector alarm means workers should:","follow emergency procedures and move to a safe area",["ignore it","silence it","go closer"],"Alarms require action.")
H('357.d.1.F',3,"An engineering control such as a ventilation system:","removes hazards at the source",["causes hazards","replaces PPE completely","stops work"],"Engineering controls reduce exposure.")
H('357.d.1.F',4,"Guards on rotating machinery are an example of:","an engineering control",["a lunch break","a company party","a schedule"],"Guards physically separate people.")
H('357.d.1.G',3,"Personal protective equipment that protects hearing is:","earplugs or earmuffs",["a hat","sunglasses","gloves"],"Hearing protection reduces noise.")
H('357.d.1.G',4,"PPE is considered the last line of defense because it:","does not remove the hazard",["is always perfect","replaces training","is optional"],"Controls at the source are preferred.")
H('357.d.1.H',3,"A noise dosimeter measures a worker's:","noise exposure",["height","weight","speed"],"Dosimeters track noise levels.")
H('357.d.1.H',4,"Hearing protection is generally required when noise exposure averages above:","85 decibels",["20 decibels","40 decibels","60 decibels"],"The action level is 85 dBA for 8 hours.")
H('357.d.1.I',3,"A respirator must be:","fit tested to the wearer",["borrowed","shared","decorated"],"Fit testing ensures a seal.")
H('357.d.1.I',4,"A supplied-air respirator is used when the atmosphere is:","immediately dangerous to life or health",["pleasant","cool","bright"],"IDLH atmospheres require supplied air.")
H('357.d.1.J',3,"Process operators use portable gas monitors to detect:","hazardous gases",["music","weather","traffic"],"Monitors detect toxic and flammable gases.")
H('357.d.1.J',4,"Four-gas monitors commonly detect oxygen, combustible gas, H2S, and:","carbon monoxide",["helium","neon","radon"],"CO is a common fourth sensor.")
H('357.d.2.A',3,"A spill is when a liquid is accidentally released, while a release can also include:","gases or vapors",["music","light","water vapor only"],"Releases include gases.")
H('357.d.2.A',4,"Wind direction matters during a release because it:","carries vapors toward or away from people",["changes the price","delays lunch","moves the moon"],"Evacuate crosswind or upwind.")
H('357.d.2.B',3,"Secondary containment, such as a dike around a tank, helps:","contain a spill",["start a spill","feed workers","warm tanks"],"Dikes hold leaked fluid.")
H('357.d.2.B',4,"An emergency shutdown system (ESD) is designed to:","stop a process quickly during an emergency",["increase pressure","begin production","start a spill"],"ESDs bring plants to safe condition.")
H('357.d.2.C',3,"The Occupational Safety and Health Administration is part of the:","Department of Labor",["Department of Music","Department of Art","Department of Sports"],"OSHA is under the Department of Labor.")
H('357.d.2.C',4,"The EPA, OSHA, and the Coast Guard are examples of:","government regulatory agencies",["sports leagues","music groups","school clubs"],"They enforce rules.")
H('357.d.2.D',3,"HAZCOM requires employers to label hazardous chemicals, provide safety data sheets, and:","train workers",["stop work","raise pay","close sites"],"Labels, SDSs, and training are the core.")
H('357.d.2.D',4,"A container label under HazCom includes a signal word such as:","Danger or Warning",["Hello","Goodbye","Maybe"],"Signal words show severity.")
H('357.d.2.E',3,"The three elements needed for a fire are fuel, oxygen, and:","heat",["water","wind","sound"],"The fire triangle has three elements.")
H('357.d.2.E',4,"A vapor cloud explosion can occur when flammable vapors mix with air and find:","an ignition source",["a cool breeze","dry soil","water"],"Ignition causes explosion.")
H('357.d.2.F',3,"The Maritime Transportation Security Act (MARSEC) is designed to protect ports and vessels from:","terrorism and security threats",["bad weather","low pay","lunch"],"MARSEC addresses security threats.")
H('357.d.2.F',4,"Access control at a port facility often includes credentials such as the:","TWIC card",["library card","gift card","membership card"],"TWIC is required for secure areas.")
H('357.d.3.A',3,"Lockout/tagout protects workers from hazardous:","stored energy",["lunch","gossip","sunshine"],"Stored energy can injure.")
H('357.d.3.A',4,"A slip, trip, and fall hazard on a work surface can be reduced by:","keeping walkways clean and dry",["adding clutter","removing lights","using oil"],"Housekeeping prevents falls.")
H('357.d.3.B',3,"Before working at height, a worker should wear:","a fall protection harness",["a necktie","sandals","headphones"],"Fall protection is required above six feet in construction.")
H('357.d.3.B',4,"A hazard when operating vehicles on a well site is:","limited visibility and heavy equipment traffic",["perfect visibility","no traffic","no equipment"],"Sites are busy.")
H('357.d.3.C',3,"Lightning storms at a petroleum site require workers to:","stop outdoor work and seek shelter",["climb towers","hold metal","work faster"],"Lightning is deadly.")
H('357.d.3.C',4,"High winds can adversely affect safety by making crane lifts:","unsafe",["easier","quieter","faster"],"Wind limits lifting.")
H('357.d.4.A',3,"Toxic chemicals released into air or water are examples of:","environmental pollutants",["school supplies","food","toys"],"Pollutants harm ecosystems.")
H('357.d.4.A',4,"Benzene is a toxic chemical found in petroleum that is also a:","known carcinogen",["vitamin","nutrient","flavor"],"Benzene causes cancer.")
H('357.d.4.B',3,"A Material Safety Data Sheet (MSDS), now called an SDS, lists a product's:","hazards and first aid measures",["price","color of the label","country of origin only"],"SDSs describe safe handling.")
H('357.d.4.B',4,"Section 4 of an SDS describes:","first-aid measures",["storage prices","company history","employee names"],"First aid is Section 4.")
H('357.d.4.C',3,"Under the Toxic Substances Control Act, a new chemical must be reviewed by the EPA before:","it is manufactured or sold",["it is named","it is bought","it is tested only"],"EPA reviews new chemicals.")
H('357.d.4.C',4,"A company that wants to manufacture a new chemical submits to the EPA a:","premanufacture notice",["lunch menu","school form","postcard"],"A PMN begins the review.")
H('357.d.4.D',3,"Before production begins at a new site, an operator must obtain:","required permits from regulators",["a pet","a trophy","a picture"],"Permits are required.")
H('357.d.4.D',4,"An air quality permit is required to control:","emissions from the site",["student behavior","school grades","traffic lights"],"Air permits limit emissions.")
H('357.d.4.E',3,"A spill prevention plan reduces the chance of:","oil reaching soil or water",["hunger","boredom","rain"],"Plans prevent releases.")
H('357.d.4.E',4,"Storm water controls such as berms help keep pollutants from reaching:","streams and rivers",["gas stations","classrooms","stores"],"Controls protect water.")

H('356.d.3.B',4,"On an industry circuit schematic, two parallel lines of unequal length usually mark a:","battery or cell",["resistor","switch","ground wire"],"The long and short plates are the battery symbol.")
H('356.d.8.B',4,"A bar graph is the best way to compare the monthly output of four different pumps because it:","shows separate categories side by side",["shows change over many years","hides the differences","only lists names"],"Bar graphs compare categories.")
H('357.d.1.I',4,"A filtering air-purifying respirator is NOT suitable when the air has too little:","oxygen",["dust","odor","moisture"],"Filters do not supply oxygen; supplied air is needed.")

